begin;

alter table item_catalog add column if not exists category text;
alter table item_catalog add column if not exists subcategory text;
alter table item_catalog add column if not exists keywords text[] not null default '{}'::text[];
alter table item_catalog add column if not exists variants jsonb not null default '{}'::jsonb;
alter table item_catalog add column if not exists source_name text;
alter table item_catalog add column if not exists source_ref text;
alter table item_catalog add column if not exists source_license text;
alter table item_catalog add column if not exists active boolean not null default true;

create index if not exists item_catalog_active_name_idx on item_catalog(active, lower(canonical_name));
create index if not exists item_catalog_category_idx on item_catalog(lower(category)) where active=true;
create index if not exists item_catalog_keywords_gin_idx on item_catalog using gin(keywords);

insert into item_catalog (
  canonical_name,slug,image_url,class_info,category,subcategory,keywords,base_attributes,variants,
